#!/usr/bin/env Rscript
root <- normalizePath(getwd(), winslash="/")
invisible(lapply(list.files(file.path(root,"R"), pattern="\\.R$", full.names=TRUE), source))
if (!requireNamespace("optparse", quietly=TRUE)) stop("Package 'optparse' is required by scripts/run_pipeline.R.", call.=FALSE)
op <- optparse::OptionParser(option_list=list(optparse::make_option("--config",default="config/era5_mintemp.yml"),optparse::make_option("--mode",default="plan"),optparse::make_option("--dry-run",action="store_true",default=FALSE),optparse::make_option("--execute",action="store_true",default=FALSE),optparse::make_option("--observed-end"),optparse::make_option("--future-end"),optparse::make_option("--data-root"),optparse::make_option("--overwrite",action="store_true",default=FALSE),optparse::make_option("--rebuild-all-weeks",action="store_true",default=FALSE),optparse::make_option("--verbose",action="store_true",default=FALSE))); o <- optparse::parse_args(op)
if(o$dry_run&&o$execute) stop("Use only one of --dry-run or --execute"); dry <- !isTRUE(o$execute); if(o$verbose) message("mode=",o$mode," dry_run=",dry); tryCatch({ x<-run_era5_mintemp_pipeline(o$config,o$mode,dry,o$observed_end,o$future_end,o$data_root,o$overwrite,o$rebuild_all_weeks); message("Pipeline completed: ",x$run_id," status=",x$status) }, error=function(e) { message("Fatal: ",conditionMessage(e)); quit(status=1) })
